$ok=static function(bool$v,string$m):void{if(!$v)throw new RuntimeException($m);};
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec("CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT);INSERT INTO users VALUES(1,'Admin');CREATE TABLE project_connections(id INTEGER PRIMARY KEY,project_id INTEGER,module_instance_id TEXT UNIQUE,endpoint_url TEXT,integration_status TEXT,machine_credential_encrypted TEXT,attached_by_user_id INTEGER,last_communication_at TEXT,last_error_code TEXT,updated_at TEXT);CREATE TABLE module_access_issuances(id INTEGER PRIMARY KEY AUTOINCREMENT,module_uuid TEXT,jti_hash TEXT UNIQUE,issued_by_user_id INTEGER,issued_at TEXT,expires_at TEXT);INSERT INTO project_connections VALUES(1,7,'f2941dd0-d5a7-41ec-9e8f-a840d13d4a98','https://caixas.gda.app.br','nao_integrado',NULL,1,NULL,NULL,NULL)");
$key=openssl_pkey_new(['private_key_bits'=>2048,'private_key_type'=>OPENSSL_KEYTYPE_RSA]);openssl_pkey_export($key,$private);$identity=new PlatformIdentity('9be90d4d-efc0-42bf-bdf3-8898de48851b','https://admin.gda.app.br',$private);$service=new GlobalModuleAccessService($db,new ModuleProtocolClient(new ModuleEndpointPolicy(),5,262144,fn()=>throw new RuntimeException('remote call not expected')),new ProjectConnectionRepository($db),$identity);
$handoff=$service->create(7,1);$claims=$identity->verifyGlobalAccess($handoff['access_token']);$ok($handoff['action']==='https://caixas.gda.app.br/admin-gda/auth/gda'&&!str_contains($handoff['action'],'?'),'Token apareceu na URL.');$ok($claims['purpose']==='initial_global_access'&&$claims['role']==='global_admin'&&$claims['exp']-$claims['iat']===120,'Claims iniciais inválidas.');$ok($service->consumeInitial($handoff['access_token'])['accepted']===true,'Consumo inicial falhou.');try{$service->consumeInitial($handoff['access_token']);throw new RuntimeException('Replay aceito.');}catch(ModuleAttachmentException$e){$ok($e->errorCode==='initial_access_replayed','Erro de replay incorreto.');}$expired=$identity->signGlobalAccess($claims['aud'],120,time()-300,'expired','initial_global_access');try{$service->consumeInitial($expired['token']);throw new RuntimeException('Expirado aceito.');}catch(ModuleAttachmentException$e){$ok($e->errorCode==='initial_access_invalid','Expiração incorreta.');}
